<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF Page Size Checker','description'=>'Inspect PDF page dimensions and file size in your browser.','url'=>'https://smarttoolz.in/tools/pdf-page-size-checker/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>PDF Page Size Checker</h1><p>Check basic PDF dimensions and page count.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="application/pdf"><button id="go" class="tool-btn">Check PDF</button><pre id="o"></pre></div></section></main><script>go.onclick=async()=>{let f=document.getElementById('f').files[0];if(!f)return;let s=new TextDecoder('latin1').decode(new Uint8Array(await f.arrayBuffer()).slice(0,2000000)),p=(s.match(/\/Type\s*\/Page\b/g)||[]).length,boxes=[...s.matchAll(/\/MediaBox\s*\[\s*([\d.-]+)\s+([\d.-]+)\s+([\d.-]+)\s+([\d.-]+)\s*\]/g)];let z=boxes[0];o.textContent=`Pages found: ${p}\nFile size: ${f.size.toLocaleString()} bytes\nFirst MediaBox: ${z?z[1]+' '+z[2]+' '+z[3]+' '+z[4]:'not found'}`}</script><?php smarttoolz_tool_page_end(); ?>